// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.HashSet;
import java.util.Set;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * An availability check on an already observed LMDB result pulls the following row from its source. A remove() issued
 * after that check must not reach the source, which would remove the row it pulled last instead of the row the caller
 * received last.
 */
class LmdbReplayableRemoveTest {

	@Test
	void removeAfterAvailabilityCheckDoesNotActOnThePrefetchedNamespace(@TempDir File directory) {
		var repository = new SailRepository(new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")));
		try (var connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < 4; i++) {
				connection.setNamespace("p" + i, "http://example.com/ns" + i + "/");
			}
			connection.commit();
			Set<String> delivered = new HashSet<>();
			try (var namespaces = connection.getSailConnection().getNamespaces()) {
				delivered.add(namespaces.next().getPrefix());
				assertTrue(namespaces.hasNext());
				assertThrows(UnsupportedOperationException.class, namespaces::remove,
						"The source has advanced to the following namespace, which is the one it would remove");
				while (namespaces.hasNext()) {
					delivered.add(namespaces.next().getPrefix());
					// Directly after next() the source is positioned on the row that was just handed out.
					namespaces.remove();
				}
			}
			assertEquals(Set.of("p0", "p1", "p2", "p3"), delivered);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void removeAfterAvailabilityCheckIsRejectedForAnOrderedQueryResult(@TempDir File directory) {
		var repository = new SailRepository(
				new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			connection.begin();
			for (int i = 0; i < 4; i++) {
				connection.add(values.createIRI("http://example.com/s" + i), values.createIRI("http://example.com/p"),
						values.createLiteral(i));
			}
			connection.commit();
			var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
					"SELECT ?s WHERE { ?s <http://example.com/p> ?value } ORDER BY ?value", null);
			try (var rows = connection.getSailConnection()
					.evaluate(parsed.getTupleExpr(), null, EmptyBindingSet.getInstance(), false)) {
				assertEquals("http://example.com/s0", rows.next().getValue("s").stringValue());
				assertTrue(rows.hasNext());
				assertThrows(UnsupportedOperationException.class, rows::remove,
						"The source has advanced to the following row, which is the one it would remove");
				for (int i = 1; i < 4; i++) {
					assertTrue(rows.hasNext());
					assertEquals("http://example.com/s" + i, rows.next().getValue("s").stringValue());
				}
				assertFalse(rows.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}
}
